/**
 * backfill-breakdown-elaboration.js — decide, per multi-character zh word, whether its
 * character breakdown needs a word of explanation, and write one only when it does.
 *
 * WHY
 *   `dictionaryentries_zh.breakdown` glosses each component character of a word
 *   (generated by backfill-dictionary-breakdown.js, sense-corrected by
 *   backfill-breakdown-senses.js). For most words that display is self-explanatory:
 *   会议 = 会 "meeting" + 议 "discuss" — the learner needs nothing more. For a
 *   minority the parts do NOT add up to the whole, and shown bare they MISLEAD:
 *     东西  east + west     → "thing"
 *     马虎  horse + tiger   → "careless, sloppy"
 *     矛盾  spear + shield  → "contradiction"
 *   Those are the words worth a sentence. This script asks the model to make exactly
 *   that call, and to stay silent when the breakdown is straightforward.
 *
 * WHAT IT WRITES  (migration 130)
 *   dictionaryentries_zh."breakdownElaboration" — one short English sentence, or NULL.
 *
 *   ⚠️ NULL IS A REAL ANSWER, not "not yet processed". "Straightforward, nothing to
 *   add" is the EXPECTED majority outcome, so the column cannot double as a done-gate.
 *   Evaluated-ness lives in the per-entry `enrichmentLog` stamp (migration 68) under
 *   this script's id, which is written for EVERY decided row — including the NULL
 *   ones. That stamp, not the column, is what the default WHERE gate reads.
 *
 * LENGTH BUDGET
 *   50 characters per character of word1 (2-char word → 100, 4-char chengyu → 200).
 *   The prompt states this as a CEILING and explicitly tells the model not to spend it
 *   — a 40-character sentence that lands is better than a 100-character one that
 *   rambles. Over-budget responses are retried ONCE with the overage quoted back; a
 *   second over-budget answer is left unwritten and unstamped (⚠ review line) so a
 *   later run retries it rather than silently truncating prose mid-thought.
 *
 * FLAGS
 *   --words=东西,马虎   scope to specific headwords
 *   --all               include non-discoverable entries
 *   --force             re-decide rows already stamped (clears a stale elaboration
 *                       when the verdict flips back to "straightforward")
 *   --stale             also re-decide rows stamped below the current SCRIPT_VERSION
 *   --limit=N           cap the batch
 *   --spot-check        5 random entries, NO writes, verbose
 *
 * Depends on: backfill-dictionary-breakdown.js (breakdown must exist) and, for a
 * trustworthy judgment, backfill-breakdown-senses.js (glosses must be the in-context
 * senses, not the global lead glosses).
 * Referenced by docs/BREAKDOWN_FEATURE_IMPLEMENTATION.md § 5c.
 */
import dotenv from 'dotenv';
import { fileURLToPath } from 'url';
import path from 'path';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
dotenv.config({ path: path.resolve(__dirname, '../../../.env') });

import Anthropic from '@anthropic-ai/sdk';
import db from '../../../db.js';
import { initRunLog, cachedSystem } from '../run-log.js';

const SCRIPT_VERSION = 1; // bump when this script's logic/prompt changes
const SCRIPT_ID = 'chinese/backfill-breakdown-elaboration';
const anthropic = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY });
const { stampEntries, staleClause } = initRunLog({ script: SCRIPT_ID, version: SCRIPT_VERSION, anthropic });

const MODEL = 'claude-sonnet-4-6';

// Characters of elaboration allowed per character of the headword. A CEILING, not a
// target — see the prompt, which tells the model to undershoot it.
const CHARS_PER_WORD_CHAR = 50;

// Soft target handed to the model, as a fraction of the ceiling. Stating only the
// ceiling makes it a TARGET: the first calibration run came back at 93/100, 99/100 and
// 199/200 characters, with two answers over the cap even after a retry. Naming a
// smaller number to aim at is what actually moves the length down; the ceiling stays
// the enforced limit.
const TARGET_FRACTION = 0.5;

// Stable marker so the mark-discoverable skill agent can grep review flags off stdout
// (same convention as the clusterer and the breakdown sense tagger).
const REVIEW_MARKER = '⚠ BREAKDOWN ELABORATION REVIEW';

// ── args ────────────────────────────────────────────────────────────────────
const args = process.argv.slice(2);
const hasFlag = (f) => args.includes(f);
const getArg = (name) => {
  const a = args.find((x) => x.startsWith(`${name}=`));
  return a ? a.slice(name.length + 1) : null;
};
const ALL = hasFlag('--all');
const FORCE = hasFlag('--force');
const STALE = hasFlag('--stale');
const SPOT_CHECK = hasFlag('--spot-check');
const LIMIT = getArg('--limit') ? parseInt(getArg('--limit'), 10) : null;
const wordsArg = getArg('--words');
const targetWords = wordsArg ? wordsArg.split(',').map((s) => s.trim()).filter(Boolean) : null;

// ── helpers ─────────────────────────────────────────────────────────────────
/** Codepoint-safe length — the budget is counted in characters the reader sees. */
const charLen = (s) => Array.from(String(s ?? '')).length;

/** Per-word elaboration ceiling. 2-char compound → 100, 4-char chengyu → 200. */
const budgetFor = (word) => charLen(word) * CHARS_PER_WORD_CHAR;

/** The length the model is told to aim at — comfortably inside budgetFor(). */
const targetFor = (word) => Math.round(budgetFor(word) * TARGET_FRACTION);

function parseJsonObject(text) {
  const stripped = String(text).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
  const match = stripped.match(/\{[\s\S]*\}/);
  if (!match) return null;
  try {
    const parsed = JSON.parse(match[0]);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : null;
  } catch {
    return null;
  }
}

/**
 * Render the breakdown for the prompt in WORD ORDER. The `breakdown` jsonb is keyed by
 * character, so its own key order is jsonb's (length, then bytes) — not the order the
 * characters appear in. Walking word1 restores reading order, which is exactly the
 * information the judgment is about ("do these, in this order, add up to the whole?").
 * Repeated characters (e.g. 天天) collapse to one key, so they are simply re-read.
 */
function breakdownLines(word, breakdown) {
  return Array.from(word).map((char, i) => {
    const v = breakdown?.[char];
    const def = (v && typeof v === 'object' ? v.definition : typeof v === 'string' ? v : null) || '(no gloss)';
    const sense = v && typeof v === 'object' && typeof v.sense === 'string' ? ` [sense: ${v.sense}]` : '';
    return `  ${i + 1}. ${char} = ${def}${sense}`;
  }).join('\n');
}

// ── model call ──────────────────────────────────────────────────────────────
const SYSTEM = `You judge whether a Chinese word's CHARACTER BREAKDOWN needs explaining to an English-speaking learner.

The learner is shown the word, its English definition, and a gloss for each component character. Your only question is: reading those character glosses in order, does the word's meaning follow?

Answer "straightforward": true — write NOTHING — when the parts plainly add up to the whole. This is the COMMON case and the correct default. Examples: 会议 (meeting + discuss = "meeting"), 火车 (fire + vehicle = "train"), 老师 (old + teacher = "teacher"), 学生 (study + person = "student"). Mild metaphor that a learner will still follow on their own is still straightforward.

Answer "straightforward": false — and write an elaboration — ONLY when the breakdown is genuinely opaque: the word is idiomatic, figurative, a fossilized phrase or allusion, an abbreviation of a longer expression, or a loan/phonetic transcription, so that stacking the GLOSSES AS SHOWN produces something a learner would not recognize as the definition. Examples: 东西 (east + west = "thing"), 马虎 (horse + tiger = "careless"), 矛盾 (spear + shield = "contradiction"), 沙发 (sand + emit = "sofa", a transcription).

The bar is HIGH. Most words fail it. In particular, DO NOT elaborate merely to:
- point out which sense a character carries here, or that some OTHER sense of it would be wrong — the gloss shown is already the correct in-context sense, so saying "X here means Y, not Z" tells the learner nothing new;
- explain a common suffix or bound morpheme (子, 儿, 化, 性, 员, 家 …);
- restate a transparent compound in different words (辞职 = quit + job, 回答 = return + answer, 口服 = mouth + take — all straightforward);
- narrate a literal-to-idiomatic step the glosses already make obvious.
If your sentence would essentially just re-read the glosses in order, the answer is "straightforward": true.

When you do elaborate:
- ONE sentence. Say how the parts get to the whole — the bridge, the image, or the origin.
- Do NOT restate the definition, do not repeat the character glosses verbatim, do not moralize about study technique.
- Plain English addressed to the learner. Chinese characters only where naming one is unavoidable.
- LENGTH: aim for about {{TARGET}} characters. {{BUDGET}} is a hard limit an answer may never cross, but it is NOT the goal — do not pad toward it. An answer that lands in half the space is the better answer.
- If you cannot explain the link honestly (the origin is unknown or disputed), prefer "straightforward": true over inventing folk etymology.

Respond with ONLY a JSON object:
{"straightforward": true} or {"straightforward": false, "elaboration": "<one sentence>"}`;

/**
 * Ask the model for one word's verdict.
 * @returns {{straightforward: boolean, elaboration: string|null}|null} null = unusable response
 */
async function callJudge(word, entry, retryNote, budgetOverride) {
  const budget = budgetOverride ?? budgetFor(word);
  const target = Math.round(budget * TARGET_FRACTION);
  const defs = Array.isArray(entry.definitions) ? entry.definitions.filter((d) => typeof d === 'string') : [];

  const userText = [
    `Word: ${word}`,
    entry.pronunciation ? `Pronunciation: ${entry.pronunciation}` : null,
    `Definition: ${defs.length ? defs.join('; ') : '(none)'}`,
    '',
    'Character breakdown as the learner sees it:',
    breakdownLines(word, entry.breakdown),
    '',
    `Elaboration length: aim for ~${target} characters, hard limit ${budget}.`,
    retryNote ?? null,
  ].filter((l) => l !== null).join('\n');

  try {
    const response = await anthropic.messages.create({
      model: MODEL,
      max_tokens: 600, // ceiling only; generous so a long chengyu answer can't be truncated mid-JSON
      temperature: 0.2,
      // NOTE: the system text varies per word (the budget scales with word length), so
      // the prompt cache only hits across words of the SAME length. That is the common
      // case (2-char words dominate), and per-word budgets are worth more than a
      // universal cache hit.
      system: cachedSystem(
        SYSTEM.replaceAll('{{BUDGET}}', String(budget)).replaceAll('{{TARGET}}', String(target))
      ),
      messages: [{ role: 'user', content: userText }],
    });
    const parsed = parseJsonObject(response.content[0].text);
    // Every unusable-response path flags itself: an undecided row is skipped AND left
    // unstamped, so a silent one would look identical to a straightforward one in the
    // summary while quietly costing a call on every future run.
    if (!parsed || typeof parsed.straightforward !== 'boolean') {
      console.log(`${REVIEW_MARKER} ${word}: unparseable verdict — not stamped, will retry`);
      return null;
    }
    if (parsed.straightforward) return { straightforward: true, elaboration: null };

    const elaboration = typeof parsed.elaboration === 'string' ? parsed.elaboration.trim() : '';
    if (!elaboration) {
      // "not straightforward" with nothing to say is not a usable verdict.
      console.log(`${REVIEW_MARKER} ${word}: verdict "not straightforward" but no elaboration text`);
      return null;
    }
    return { straightforward: false, elaboration };
  } catch (e) {
    console.log(`${REVIEW_MARKER} ${word}: judge call failed (${e.message})`);
    return null;
  }
}

/**
 * Full per-word decision including the one over-budget retry.
 * @returns {{elaboration: string|null}|null} null = undecided (caller must NOT stamp,
 *          so a later run retries the row rather than freezing a bad/absent answer in).
 */
async function decide(word, entry) {
  const budget = budgetFor(word);

  let verdict = await callJudge(word, entry, null);
  if (!verdict) return null;
  if (verdict.straightforward) return { elaboration: null };

  if (charLen(verdict.elaboration) > budget) {
    // Retry once with the overage quoted back. Truncating prose would cut a sentence
    // mid-thought, so the model gets one chance to say the same thing shorter.
    //
    // The retry is told a TIGHTER limit than the real one (the soft target). A model
    // asked for "at most 100" reliably lands at 101-102 — near-misses that the real
    // cap would then discard entirely. Aiming it at half the cap means even a sizeable
    // overshoot still clears the actual ceiling.
    const over = charLen(verdict.elaboration);
    const retryBudget = targetFor(word);
    verdict = await callJudge(
      word,
      entry,
      `Your previous answer was ${over} characters — too long. Rewrite it in at most ${retryBudget} characters: cut the restatement and keep only the bridge from the parts to the whole. If it cannot be said that briefly, answer "straightforward": true.`,
      retryBudget
    );
    if (!verdict) return null;
    if (verdict.straightforward) return { elaboration: null };
    if (charLen(verdict.elaboration) > budget) {
      console.log(`${REVIEW_MARKER} ${word}: still ${charLen(verdict.elaboration)}/${budget} chars after retry — left unwritten`);
      return null;
    }
  }

  return { elaboration: verdict.elaboration };
}

// ── main ────────────────────────────────────────────────────────────────────
async function run() {
  console.log('Starting breakdown-elaboration backfill...\n');
  if (targetWords?.length) console.log(`🎯 Scoped to: ${targetWords.join(', ')}`);
  if (SPOT_CHECK) console.log('🔎 SPOT-CHECK mode — NO writes\n');

  const client = await db.getClient();
  try {
    const conds = [
      `language = 'zh'`,
      `char_length(word1) > 1`,
      `breakdown IS NOT NULL`,
      `breakdown <> 'null'::jsonb`,
    ];
    const params = [];
    // A --words run targets exactly those rows, INCLUDING not-yet-discoverable ones —
    // that is how the lazy-enrichment worker and /oracle-backfill drive this step for a
    // word being brought up to discoverable. Untargeted full-table runs keep the gate.
    // (Same convention as backfill-classifier.js; --all forces the gate off outright.)
    if (!ALL && !targetWords?.length) conds.push('discoverable = TRUE');

    // Done-gate. NOT `breakdownElaboration IS NULL` — NULL is a legitimate verdict, so
    // gating on it would re-judge (and re-pay for) every straightforward word forever.
    // Default: rows this script has never stamped. --stale: also rows stamped below the
    // current SCRIPT_VERSION. --force: no gate at all.
    if (!FORCE) {
      const neverStamped = `NOT (COALESCE("enrichmentLog", '{}'::jsonb) ? '${SCRIPT_ID}')`;
      conds.push(STALE ? staleClause() : neverStamped);
    }
    if (targetWords?.length) { params.push(targetWords); conds.push(`word1 = ANY($${params.length})`); }

    // Spot-check samples RANDOMLY (quality across the corpus, not just the lowest ids);
    // the real run keeps deterministic id order for resumability.
    let sql = `SELECT id, word1, pronunciation, definitions, breakdown, "breakdownElaboration"
                 FROM dictionaryentries_zh
                WHERE ${conds.join(' AND ')}
                ORDER BY ${SPOT_CHECK ? 'RANDOM()' : 'id'}`;
    if (SPOT_CHECK) sql += ` LIMIT ${LIMIT ?? 5}`;
    else if (LIMIT) sql += ` LIMIT ${LIMIT}`;

    const { rows: entries } = await client.query(sql, params);
    console.log(`Found ${entries.length} entries to judge\n`);
    if (entries.length === 0) { console.log('No entries to process.'); return; }

    let processed = 0, elaborated = 0, straightforward = 0, undecided = 0, failed = 0;
    for (const entry of entries) {
      processed++;
      try {
        const decision = await decide(entry.word1, entry);
        if (!decision) { undecided++; continue; } // not stamped — a later run retries

        if (SPOT_CHECK) {
          if (decision.elaboration) {
            console.log(`✎ ${entry.word1} (${charLen(decision.elaboration)}/${budgetFor(entry.word1)} chars): ${decision.elaboration}`);
          } else {
            console.log(`— ${entry.word1}: straightforward, no elaboration`);
          }
        } else {
          // Always write the column — a --force re-run whose verdict flipped back to
          // "straightforward" must CLEAR the stale elaboration, not leave it stranded.
          await client.query(
            `UPDATE dictionaryentries_zh SET "breakdownElaboration" = $1 WHERE id = $2`,
            [decision.elaboration, entry.id]
          );
          await stampEntries(client, 'dictionaryentries_zh', entry.id);
        }
        if (decision.elaboration) elaborated++; else straightforward++;

        if (!SPOT_CHECK && processed % 50 === 0) {
          console.log(`Progress: ${processed}/${entries.length} (${Math.round((processed / entries.length) * 100)}%)`);
        }
      } catch (e) {
        failed++;
        console.error(`Failed ID ${entry.id} "${entry.word1}": ${e.message}`);
      }
    }

    console.log('\n' + '='.repeat(60));
    console.log('BREAKDOWN ELABORATION SUMMARY');
    console.log('='.repeat(60));
    console.log(`Processed:        ${processed}`);
    console.log(`Elaborated:       ${elaborated}${SPOT_CHECK ? ' (not written — spot-check)' : ''}`);
    console.log(`Straightforward:  ${straightforward} (written as NULL)`);
    console.log(`Undecided:        ${undecided} (unusable/over-budget response — not stamped, will retry)`);
    console.log(`Failed:           ${failed}`);
    console.log('='.repeat(60));
  } catch (e) {
    console.error('Fatal error during backfill:', e);
    throw e;
  } finally {
    client.release();
    await db.pool.end();
  }
}

run().catch((e) => { console.error('Fatal error:', e); process.exit(1); });
